set -u
cd "$(dirname "$0")"
retry() { local out=$1; shift; for i in 1 2 3; do "$@" > "$out"; [ "$(wc -w < "$out")" -gt 300 ] && return 0; sleep 30; done; }
PANEL="Panel (Indian viewers at 10 pm, English only): 1 TCS support engineer Pune 24; 2 CA Ahmedabad 31; 3 HR exec Bengaluru 28; 4 bank RM Lucknow 35; 5 school teacher Jaipur 38; 6 BTech final-year Hyderabad 21; 7 FP&A analyst Gurgaon 25; 8 IB/equity research associate Mumbai 33; 9 Big 4 consulting analyst Bengaluru 24; 10 strategy consulting manager Mumbai 32; 11 performance marketing exec Delhi 26; 12 FMCG brand manager Mumbai 34; 13 startup backend dev Bengaluru 27; 14 ML engineer Hyderabad 30; 15 gym trainer Delhi 29 (non-tech); 16 BCom student Kolkata 20."
BRIEF="CREATOR'S STRUCTURE (non-negotiable; architecture is his signature, it worked in past reels): 1) HOOK. 2) People are doing cool things with Fable 5.2 (his observation + the Fermat 1,000-agent proof as the wow example). 3) 'I read the 264-page paper': LEARNINGS FROM THE PAPER told as ARCHITECTURE: what is and isn't disclosed, how it is built and trained (one model two configurations; safeguard classifiers + fallback routing; always-on hidden thinking + effort dial; training data pipeline + constitution post-training; training-time reward hacking; white-box probes / thinks without writing it out / test awareness; 1M context limits). Each learning = one hand-drawn line/architecture diagram that builds up piece by piece into ONE full architecture of Fable 5.2 by the end of the section. Pick the 4-5 most striking; keep spoken lines short, details on screen. 4) PERFORMANCE ON THE WEIGHT MEASUREMENT TASK (example plate 340 g: Fable 295, Opus 290, Haiku 410; one percentage: 34% lower portion error than Haiku across 25 plates; one line that no special training is published, it reasons from scale cues). 5) FABLE IN HIS EXISTING SYSTEMS AS ARCHITECTURE: Meal Analyser pipeline with Fable in the vision slot, and Content OS routing (Fable thinks, cheaper models check and do). 6) ENDING WITH TIPS: his spend tips + Anthropic's Pro tips (Fable on Pro = paid credits; Sonnet for most things; lower effort; tools off; new chat per topic) + one line of evidence: on 11 everyday jobs Haiku matched Fable at 97% lower cost. CTA 'Comment FABLE' for the architecture + tips cards; Saturday Workout Analyser tease.
Two versions with the same body from section 2 onward: MAIN = money hook, positive tone ('Nearly forty times the price. Same scores.' family; it must pay off in section 6 and loop back). TRIAL = creator's exact hook 'If the CEO says AI could be a risk to humanity, why did he just launch this?', fear tone, full quote with 'if managed poorly' on screen, never imply he said it after the launch (he said it ~7 weeks before); in TRIAL the paper section leans on the unsettling learnings (test awareness, hides reasoning from a monitor 1 in 4 when told to, guessing the answer key) and resolves into control. Also propose ONE architecture-led hook for the main reel as an alternative (e.g. about what Anthropic won't show you vs what the paper reveals). Percentages over absolute numbers except the bill and the example plate grams. 80-90 s at 1.1x incl. cards. English only."
retry ARCH_v1.md bash -c "{ cat facts.md arch_facts.md creator_inputs.md; echo; echo \"\$1\"; cat <<'P'
Output:
# MAIN REEL (positive) - beat table: Beat | Section | Spoken (exact) | Top-half visual (diagram: what draws on which word; the architecture builds up) | On-screen text | Viewer feels | Music/SFX ; runtime
# TRIAL REEL (fear) - same columns, mark beats identical to MAIN; runtime
# ARCHITECTURE-LED HOOK (alternative for MAIN) with rationale
# DIAGRAM LIST (every diagram: id, what it shows, build order)
P
} | claude -p --model claude-fable-5-2 --tools '' 2>/dev/null" _ "$BRIEF"
echo v1
retry ARCH_SURVEY.md bash -c "{ echo \"Independent engagement + accuracy survey of two reel versions (another model wrote them). $PANEL Per version: per-persona row (3 s hold Y/N, watch %, emotion felt, relatability, learned, send, save 0-10, comment FABLE Y/N, what was beyond them); group averages (mass 2-5,12,15,16 / fin-consult-mktg 7-12 / builders 1,6,13,14) and overall. Specifically judge the ARCHITECTURE section: is it clear, does the build-up work, which learnings land and which lose people. Flag any claim not supported by FACTS/ARCH FACTS. Top 6 fixes. Under 1100 words.\"; cat ARCH_v1.md; echo FACTS:; cat facts.md arch_facts.md creator_inputs.md; } | claude -p --model claude-opus-5-5 --tools '' 2>/dev/null"
echo survey
retry ARCH_FINAL.md bash -c "{ cat facts.md arch_facts.md creator_inputs.md; echo; echo \"\$1\"; echo; echo 'YOUR v1:'; cat ARCH_v1.md; echo; echo 'INDEPENDENT SURVEY:'; cat ARCH_SURVEY.md; echo; echo 'TASK: Final pass: apply every fix that keeps the creator structure and accuracy; keep the architecture section his signature. Same output sections as v1.'; } | claude -p --model claude-fable-5-2 --tools '' 2>/dev/null" _ "$BRIEF"
echo ARCH_DONE
